from pathlib import Path
import sys,json,hashlib,re
W=Path(__file__).resolve().parent
sys.path.insert(0,'/Volumes/LaCie/open-commentary/_tools');from build_repo import load_commentary
c=load_commentary(str(W));save=lambda p,v:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
save(W/'sources/review-art-90-106-before-hashes.json',{k:hashlib.sha256(v.encode()).hexdigest() for k,v in c.items()})
add={
'art-93':'De uitzondering van lid 2 volgt precies de goederen van artikel 21 onder 1, niet alle in artikel 21 genoemde vermogensbestanddelen. Ook de onder artikel 92 onmiddellijk tegen ontvangbewijs ingenomen goederen blijven buiten het zegel. De overige bedrijfsmiddelen zijn slechts uitgezonderd indien het bedrijf daadwerkelijk wordt voortgezet; een nog niet uitgevoerd voornemen tot verkoop of herstart maakt niet automatisch alles vrij van verzegeling.',
'art-98':'Artikel 78 noemt het al dan niet voortzetten uitdrukkelijk als adviesonderwerp. De curator is aan dat advies niet gebonden, maar bij afwijking gelden de kennisgeving en eventuele opschorting van artikel 79. Een commissieadvies vervangt dus geen besluit van de curator. Voor een voortzettingsvoorstel na het ontbreken of verwerpen van een akkoord ter verificatievergadering geldt de afzonderlijke procedure vanaf artikel 173a; de aanvankelijke beheersbeslissing bepaalt die latere beslissing niet.',
'art-100':'Als er een schuldeiserscommissie is, moet de curator over de toepassing van artikel 100 ook haar advies vragen: artikel 78 noemt dit artikel uitdrukkelijk. Het vaststellen van de som door de rechter-commissaris blijft daarnaast nodig. Het gaat om een bevoegdheid om naar omstandigheden uit de boedel te betalen, niet om een door deze bepaling los van de beschikbare middelen gegarandeerde uitkering.',
'art-101':'Artikel 176 lid 1 maakt openbare verkoop mogelijk en verlangt voor onderhandse verkoop in beginsel toestemming van de rechter-commissaris. De uitzondering geldt wanneer de gezamenlijke waarde volgens de boedelbeschrijving niet meer dan € 2.000 bedraagt, met inachtneming van eerder door de curator verkochte goederen. Dat is geen vrijstelling van € 2.000 per afzonderlijke transactie: opsplitsen van een partij heropent de ruimte niet. Lid 2 van artikel 176 verlangt voor niet spoedig of niet voor vereffening vatbare baten een door de rechter-commissaris goedgekeurde beschikkingswijze. Artikel 78 noemt artikel 101 bovendien als verplicht adviesonderwerp als een commissie bestaat. Een dringend verkoopbelang maakt deze concrete regels niet overbodig.',
'art-105':'De informatieplicht en de waarborgen bij het afdwingen daarvan moeten samen worden beoordeeld. In [HR 24 januari 2014, ECLI:NL:HR:2014:161](cases/HR-2014-161.md), rov. 3.5–3.8, bleef dwang tot boedelinformatie mogelijk, maar werd bij de daar verlangde wilsafhankelijke inlichtingen en mogelijk strafrechtelijk gebruik een gebruiksrestrictie noodzakelijk geacht. De Hoge Raad verbond die restrictie aan de afwijzing van het ontslagverzoek. Dit vormt geen algemeen recht alle boedelinformatie te weigeren en beslist niet dat ieder bestaand document dezelfde bescherming geniet. De uitspraak betreft een oudere tekst; de huidige spontane informatieplicht en buitenlandse medewerking worden hier aan de huidige leden 1 en 2 ontleend, niet aan die beschikking.',
'art-105a':'De uitbreiding van de medewerkingsplicht levert op zichzelf geen bevoegdheid tot extra contactbeperkingen tijdens faillissementsbewaring op. Dat volgt uit [HR 13 maart 2026, ECLI:NL:HR:2026:400](cases/HR-2026-400.md), rov. 3.2–3.5: de Hoge Raad betrekt de uitbreiding van artikelen 105 en 105a, maar vindt daarin geen kenbare wettelijke basis voor zulke beperkingen. De praktische wens gegevens veilig te stellen vervangt die basis niet. Dit oordeel neemt de verplichting tot ongeschonden overdracht en het verschaffen van leesmiddelen niet weg; het begrenst een specifiek dwangmiddel.',
'art-106':'De personele uitbreiding betreft de gehele reeks artikelen 87 tot en met 92. Zij omvat dus niet alleen informatie en bewaring, maar bijvoorbeeld ook de woonplaatsregel van artikel 91; de voorwaarden van ieder afzonderlijk artikel blijven gelden. De terugkijktermijn van drie jaar betreft de voormalige bestuurders en commissarissen, niet een algemene beperking van de te onderzoeken administratie tot drie jaar. Bij een indirect bestuur verlangt lid 2 onder b onderzoek naar de daarin genoemde rechtspersonen en vennoten; het enkele aandeelhouderschap wordt niet als zelfstandige categorie genoemd. De gelijkstelling bewijst evenmin civielrechtelijke bestuurdersaansprakelijkheid: dit artikel regelt toepassing van de opgesomde faillissementsverplichtingen en maatregelen.'}
for p in (W/'commentary').glob('*.md'):
 s=p.read_text();parts=re.split(r'(?m)(^=== \S+\n)',s)
 for i in range(1,len(parts),2):
  k=parts[i].strip()[4:]
  if k in add:parts[i+1]=parts[i+1].rstrip()+'\n\n'+add[k]+'\n\n'
 out=''.join(parts)
 if out!=s:p.write_text(out)
